def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"], vars["v4"], vars["v5"]]
    threshold = 4000.0
    value = sum(1 for item in values if item > threshold)
    return {
        "value": value,
        "trace": {
            "values": values,
            "threshold": threshold,
            "qualifying_values": [item for item in values if item > threshold],
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "years"
            }
        }
    }
